import itertools

def solve_small(n, k_vals):
    results = {}
    for k in k_vals:
        all_win = True
        # For each combination of k cells
        for combo in itertools.combinations(range(n*n), k):
            grid = [0] * (n*n)
            for idx in combo:
                grid[idx] = 1

            # Simulate
            visited = set()
            if tuple(grid) in visited:
                pass # already seen

            queue = [tuple(grid)]
            visited = {tuple(grid)}
            won = False
            while queue:
                curr = queue.pop(0)
                if sum(curr) == n*n:
                    won = True
                    break

                # Try all 2x2 squares
                for r in range(n-1):
                    for c in range(n-1):
                        idx = [r*n+c, r*n+c+1, (r+1)*n+c, (r+1)*n+c+1]
                        count = sum(curr[i] for i in idx)
                        if count == 3:
                            # Rule 1
                            new_grid = list(curr)
                            for i in idx:
                                if new_grid[i] == 0:
                                    new_grid[i] = 1
                            new_grid_t = tuple(new_grid)
                            if new_grid_t not in visited:
                                visited.add(new_grid_t)
                                queue.append(new_grid_t)
                        elif count == 2:
                            # Rule 2
                            new_grid = list(curr)
                            for i in idx:
                                new_grid[i] = 1 - new_grid[i]
                            new_grid_t = tuple(new_grid)
                            if new_grid_t not in visited:
                                visited.add(new_grid_t)
                                queue.append(new_grid_t)
                if won:
                    break
            if not won:
                all_win = False
                break
        results[k] = all_win
    return results

