def can_win_bitmask(grid_mask, n):
    queue = [grid_mask]
    visited = {grid_mask}
    target = (1 << (n*n)) - 1

    # Precompute 2x2 masks
    masks = []
    for r in range(n-1):
        for c in range(n-1):
            idx = [r*n+c, r*n+c+1, (r+1)*n+c, (r+1)*n+c+1]
            m = 0
            for i in idx:
                m |= (1 << i)
            masks.append((m, idx))

    while queue:
        curr = queue.pop(0)
        if curr == target:
            return True

        for m, idx in masks:
            # Count infected in the 2x2
            count = 0
            for i in idx:
                if (curr >> i) & 1:
                    count += 1

            if count == 3:
                # Rule 1: the 0 becomes 1
                new_mask = curr | m
                if new_mask not in visited:
                    visited.add(new_mask)
                    queue.append(new_mask)
            elif count == 2:
                # Rule 2: 1s become 0s, 0s become 1s
                # This is equivalent to: curr XOR m
                # Wait, the rule says: "infected sections become sterile, and sterile sections become infected"
                # This is indeed: for all 4 cells, flip them.
                # But only for those 4. So curr ^ m.
                new_mask = curr ^ m
                if new_mask not in visited:
                    visited.add(new_mask)
                    queue.append(new_mask)
    return False

