def can_win_all_configs(n):
    target = (1 << (n*n)) - 1
    masks = []
    for r in range(n-1):
        for c in range(n-1):
            idx = [r*n+c, r*n+c+1, (r+1)*n+c, (r+1)*n+c+1]
            m = 0
            for i in idx:
                m |= (1 << i)
            masks.append((m, idx))

    winners = {target}
    queue = [target]

    while queue:
        curr = queue.pop(0)
        for m, idx in masks:
            count = 0
            for i in idx:
                if (curr >> i) & 1:
                    count += 1
            if count == 4:
                for i in idx:
                    prev = curr ^ (1 << i)
                    if prev not in winners:
                        winners.add(prev)
                        queue.append(prev)
            elif count == 2:
                prev = curr ^ m
                if prev not in winners:
                    winners.add(prev)
                    queue.append(prev)
    return winners

def check_n(n):
    winners = can_win_all_configs(n)
    for k in range(1, n*n + 1):
        all_win = True
        # Instead of iterating all 2^(n*n), let's use combinations
        import itertools
        for combo in itertools.combinations(range(n*n), k):
            state = 0
            for i in combo:
                state |= (1 << i)
            if state not in winners:
                all_win = False
                break
        if all_win:
            return k
    return n*n

