import itertools
def check_n_fast(n):
    winners = can_win_all_configs(n)
    for k in range(1, n*n + 1):
        all_win = True
        # To check if all states with k bits are in winners
        # We can iterate through all states with k bits.
        # For n=5, k=9, combinations(25, 9) = 2042975. That's okay.
        for combo in itertools.combinations(range(n*n), k):
            state = 0
            for i in combo:
                state |= (1 << i)
            if state not in winners:
                all_win = False
                break
        if all_win:
            return k
    return n*n

